var data = {lines:[
{"lineNum":"    1","line":"#!/usr/bin/env bash"},
{"lineNum":"    2","line":"#"},
{"lineNum":"    3","line":"# Fails when a measured shell file contains a `\\` line continuation."},
{"lineNum":"    4","line":"#"},
{"lineNum":"    5","line":"# kcov instruments every file under scripts/ and bin/, and bash attributes a multi-line command to its"},
{"lineNum":"    6","line":"# *final* line. So the first line of a continuation is reported as never executed and the lines between"},
{"lineNum":"    7","line":"# are not instrumented at all: a command spread over four lines contributes one covered line and three"},
{"lineNum":"    8","line":"# that look dead. The loss is silent — it appears as a coverage gate with less headroom than the code"},
{"lineNum":"    9","line":"# deserves, never as a diff that did anything wrong — which is why it is checked mechanically rather"},
{"lineNum":"   10","line":"# than remembered. Seventeen of them had accumulated before anyone counted."},
{"lineNum":"   11","line":"#"},
{"lineNum":"   12","line":"# Line length is free here and a continuation is not, so the fix is always the same: put the command on"},
{"lineNum":"   13","line":"# one long line."},
{"lineNum":"   14","line":"#"},
{"lineNum":"   15","line":"# What this does not catch: a command spread over several lines *without* a backslash, which a quoted"},
{"lineNum":"   16","line":"# multi-line awk or jq program is the usual way to write. Bash attributes those to their final line for"},
{"lineNum":"   17","line":"# exactly the same reason, and the interior lines are not even bash. The convention that keeps them out"},
{"lineNum":"   18","line":"# is a separate one — a program longer than a line or two lives in its own file, where check-programs.sh"},
{"lineNum":"   19","line":"# syntax-checks it and nothing measures it as bash."},
{"lineNum":"   20","line":"#"},
{"lineNum":"   21","line":"# Usage:"},
{"lineNum":"   22","line":"#   ./check-continuations.sh [directory...]"},
{"lineNum":"   23","line":"#"},
{"lineNum":"   24","line":"# Arguments:"},
{"lineNum":"   25","line":"#   directory  Roots to search; defaults to scripts/ and bin/, which is what kcov measures. test/ is"},
{"lineNum":"   26","line":"#              deliberately outside that set: nothing measures the suite, so a continuation there costs"},
{"lineNum":"   27","line":"#              nothing and reads better than a long line."},
{"lineNum":"   28","line":"#"},
{"lineNum":"   29","line":"# Exits non-zero if any file carries a continuation."},
{"lineNum":"   30","line":""},
{"lineNum":"   31","line":"set -o errexit","class":"lineCov","hits":"1","order":"192",},
{"lineNum":"   32","line":"set -o nounset","class":"lineCov","hits":"1","order":"191",},
{"lineNum":"   33","line":"set -o pipefail","class":"lineCov","hits":"1","order":"189",},
{"lineNum":"   34","line":""},
{"lineNum":"   35","line":"SCRIPT_DIR=\"$(cd \"$(dirname \"$0\")\" && pwd -P)\"","class":"lineCov","hits":"1","order":"187",},
{"lineNum":"   36","line":"readonly SCRIPT_DIR","class":"lineCov","hits":"1","order":"186",},
{"lineNum":"   37","line":"# shellcheck source=../_lib/paths.sh"},
{"lineNum":"   38","line":"source \"${SCRIPT_DIR}/../_lib/paths.sh\"","class":"lineCov","hits":"1","order":"185",},
{"lineNum":"   39","line":"# shellcheck source=../_lib/log.sh"},
{"lineNum":"   40","line":"source \"${SCRIPT_DIR}/../_lib/log.sh\"","class":"lineCov","hits":"1","order":"181",},
{"lineNum":"   41","line":""},
{"lineNum":"   42","line":"# A line whose last character is a backslash that is not itself escaped. The leading alternation is what"},
{"lineNum":"   43","line":"# excludes a line ending in two backslashes: there the final backslash is a literal, the command ends,"},
{"lineNum":"   44","line":"# and kcov sees nothing unusual."},
{"lineNum":"   45","line":"readonly CONTINUATION_RE=\'(^|[^\\])\\\\$\'","class":"lineCov","hits":"1","order":"202",},
{"lineNum":"   46","line":""},
{"lineNum":"   47","line":"# The one measured-path exception, because it is not measured: test/test_helper.bash passes"},
{"lineNum":"   48","line":"# --exclude-pattern=run-coverage.sh to kcov, so continuations there cost no coverage. Matched as a path"},
{"lineNum":"   49","line":"# relative to the repository root, so it exempts that one file rather than every file with the name."},
{"lineNum":"   50","line":"readonly EXEMPT_PATH=\"bin/coverage/run-coverage.sh\"","class":"lineCov","hits":"1","order":"180",},
{"lineNum":"   51","line":""},
{"lineNum":"   52","line":"#######################################"},
{"lineNum":"   53","line":"# Prints usage instructions to stdout."},
{"lineNum":"   54","line":"#######################################"},
{"lineNum":"   55","line":"show_usage() {"},
{"lineNum":"   56","line":"  cat <<EOF","class":"lineCov","hits":"1","order":"204",},
{"lineNum":"   57","line":"Usage: $(basename \"$0\") [directory...]"},
{"lineNum":"   58","line":""},
{"lineNum":"   59","line":"Fails when a shell file under the given directories (default: scripts/ and bin/) contains a backslash"},
{"lineNum":"   60","line":"line continuation, which kcov cannot attribute to the lines it spans."},
{"lineNum":"   61","line":""},
{"lineNum":"   62","line":"Options:"},
{"lineNum":"   63","line":"  -h    Show this help message."},
{"lineNum":"   64","line":"EOF"},
{"lineNum":"   65","line":"}"},
{"lineNum":"   66","line":""},
{"lineNum":"   67","line":"#######################################"},
{"lineNum":"   68","line":"# Reports every line continuation in one file."},
{"lineNum":"   69","line":"# Globals:"},
{"lineNum":"   70","line":"#   REPO_ROOT, CONTINUATION_RE"},
{"lineNum":"   71","line":"# Arguments:"},
{"lineNum":"   72","line":"#   path: Shell file to read."},
{"lineNum":"   73","line":"# Returns:"},
{"lineNum":"   74","line":"#   0 when the file has none, 1 otherwise."},
{"lineNum":"   75","line":"#######################################"},
{"lineNum":"   76","line":"check_file() {"},
{"lineNum":"   77","line":"  local path=\"$1\" rel=\"${1#\"${REPO_ROOT}/\"}\"","class":"lineCov","hits":"1","order":"182",},
{"lineNum":"   78","line":"  local found=0 hit","class":"lineCov","hits":"1","order":"176",},
{"lineNum":"   79","line":"  # grep exits 1 for no match, which is the passing case here, so its status is discarded and the"},
{"lineNum":"   80","line":"  # presence of output is what decides."},
{"lineNum":"   81","line":"  while IFS= read -r hit; do","class":"lineCov","hits":"1","order":"174",},
{"lineNum":"   82","line":"    log_error \"${rel}:${hit%%:*} ends with a line continuation.\"","class":"lineCov","hits":"1","order":"194",},
{"lineNum":"   83","line":"    found=1","class":"lineCov","hits":"1","order":"197",},
{"lineNum":"   84","line":"  done < <(grep -nE \"${CONTINUATION_RE}\" \"${path}\" || true)","class":"lineNoCov","hits":"0",},
{"lineNum":"   85","line":"  return \"${found}\"","class":"lineCov","hits":"1","order":"179",},
{"lineNum":"   86","line":"}"},
{"lineNum":"   87","line":""},
{"lineNum":"   88","line":"#######################################"},
{"lineNum":"   89","line":"# Checks every shell file under the given roots."},
{"lineNum":"   90","line":"#"},
{"lineNum":"   91","line":"# Symlinks are followed: the test fixtures mirror bin/ as links into the real tree, and a check that"},
{"lineNum":"   92","line":"# skipped them would pass by looking at nothing."},
{"lineNum":"   93","line":"# Globals:"},
{"lineNum":"   94","line":"#   REPO_ROOT, EXEMPT_PATH"},
{"lineNum":"   95","line":"# Arguments:"},
{"lineNum":"   96","line":"#   Directories to search."},
{"lineNum":"   97","line":"# Returns:"},
{"lineNum":"   98","line":"#   0 when no file carries a continuation, 1 otherwise."},
{"lineNum":"   99","line":"#######################################"},
{"lineNum":"  100","line":"check_all() {"},
{"lineNum":"  101","line":"  local failed=0 count=0 path","class":"lineCov","hits":"1","order":"200",},
{"lineNum":"  102","line":"  while IFS= read -r -d \'\' path; do","class":"lineCov","hits":"1","order":"201",},
{"lineNum":"  103","line":"    if [[ \"${path#\"${REPO_ROOT}/\"}\" == \"${EXEMPT_PATH}\" ]]; then","class":"lineCov","hits":"1","order":"190",},
{"lineNum":"  104","line":"      continue","class":"lineCov","hits":"1","order":"203",},
{"lineNum":"  105","line":"    fi"},
{"lineNum":"  106","line":"    count=$(( count + 1 ))","class":"lineCov","hits":"1","order":"183",},
{"lineNum":"  107","line":"    check_file \"${path}\" || failed=1","class":"lineCov","hits":"1","order":"177",},
{"lineNum":"  108","line":"  done < <(find -L \"$@\" -type f -name \'*.sh\' -print0 | sort -z)","class":"lineNoCov","hits":"0",},
{"lineNum":"  109","line":""},
{"lineNum":"  110","line":"  if (( failed )); then","class":"lineCov","hits":"1","order":"175",},
{"lineNum":"  111","line":"    log_error \"A continuation hides the lines it spans from kcov. Put the command on one long line.\"","class":"lineCov","hits":"1","order":"195",},
{"lineNum":"  112","line":"    return 1","class":"lineCov","hits":"1","order":"198",},
{"lineNum":"  113","line":"  fi"},
{"lineNum":"  114","line":""},
{"lineNum":"  115","line":"  log_info \"All ${count} shell file(s) are free of line continuations.\"","class":"lineCov","hits":"1","order":"205",},
{"lineNum":"  116","line":"}"},
{"lineNum":"  117","line":""},
{"lineNum":"  118","line":"#######################################"},
{"lineNum":"  119","line":"# Parses arguments and checks every file."},
{"lineNum":"  120","line":"# Globals:"},
{"lineNum":"  121","line":"#   REPO_ROOT, SCRIPTS_DIR"},
{"lineNum":"  122","line":"# Arguments:"},
{"lineNum":"  123","line":"#   See show_usage."},
{"lineNum":"  124","line":"#######################################"},
{"lineNum":"  125","line":"main() {"},
{"lineNum":"  126","line":"  if [[ \"${1:-}\" == \"-h\" || \"${1:-}\" == \"--help\" ]]; then","class":"lineCov","hits":"1","order":"206",},
{"lineNum":"  127","line":"    show_usage","class":"lineCov","hits":"1","order":"173",},
{"lineNum":"  128","line":"    exit 0","class":"lineCov","hits":"1","order":"172",},
{"lineNum":"  129","line":"  fi"},
{"lineNum":"  130","line":""},
{"lineNum":"  131","line":"  local -a roots=(\"$@\")","class":"lineCov","hits":"1","order":"171",},
{"lineNum":"  132","line":"  if (( ${#roots[@]} == 0 )); then","class":"lineCov","hits":"1","order":"170",},
{"lineNum":"  133","line":"    roots=(\"${SCRIPTS_DIR}\" \"${REPO_ROOT}/bin\")","class":"lineCov","hits":"1","order":"169",},
{"lineNum":"  134","line":"  fi"},
{"lineNum":"  135","line":""},
{"lineNum":"  136","line":"  # Resolved to physical paths, because both the exemption and the reported path compare a found path"},
{"lineNum":"  137","line":"  # against REPO_ROOT, which is itself physical. Left as given, a root reached through a symlink — which"},
{"lineNum":"  138","line":"  # is every root under a macOS temp directory, /var being a link to /private/var — yields paths that"},
{"lineNum":"  139","line":"  # never match the prefix, so the exemption would quietly apply to nothing and every path would print"},
{"lineNum":"  140","line":"  # in full."},
{"lineNum":"  141","line":"  local -a resolved=()","class":"lineCov","hits":"1","order":"193",},
{"lineNum":"  142","line":"  local root","class":"lineCov","hits":"1","order":"196",},
{"lineNum":"  143","line":"  for root in \"${roots[@]}\"; do","class":"lineCov","hits":"1","order":"199",},
{"lineNum":"  144","line":"    if [[ ! -d \"${root}\" ]]; then","class":"lineCov","hits":"1","order":"178",},
{"lineNum":"  145","line":"      log_error \"Directory not found: ${root}\"","class":"lineCov","hits":"1","order":"168",},
{"lineNum":"  146","line":"      exit 1","class":"lineCov","hits":"1","order":"167",},
{"lineNum":"  147","line":"    fi"},
{"lineNum":"  148","line":"    resolved+=(\"$(cd \"${root}\" && pwd -P)\")","class":"lineCov","hits":"1","order":"166",},
{"lineNum":"  149","line":"  done"},
{"lineNum":"  150","line":""},
{"lineNum":"  151","line":"  check_all \"${resolved[@]}\"","class":"lineCov","hits":"1","order":"188",},
{"lineNum":"  152","line":"}"},
{"lineNum":"  153","line":""},
{"lineNum":"  154","line":"# Only run when executed, not when sourced — the test suite sources this file to exercise its"},
{"lineNum":"  155","line":"# individual functions."},
{"lineNum":"  156","line":"if [[ \"${BASH_SOURCE[0]}\" == \"${0}\" ]]; then","class":"lineCov","hits":"1","order":"184",},
{"lineNum":"  157","line":"  main \"$@\"","class":"lineCov","hits":"1","order":"165",},
{"lineNum":"  158","line":"fi"},
]};
